// info: Checkout[0] Calling payment service
// info: Checkout[0] Payment finished, ok=True
// info: Checkout[0] Payment finished, ok=False

using System.Diagnostics;
using System.Diagnostics.Metrics;

public class Checkout(ILogger<Checkout> log, IPayments payments)
{
    static readonly ActivitySource Source = new("Shop.Checkout");
    static readonly Meter Meter = new("Shop.Checkout");
    static readonly Counter<long> Declines =
        Meter.CreateCounter<long>("checkout.declines");

    public async Task<bool> PayAsync(Order order)
    {
        // Trace: a span for this one call, tagged with its order
        using var span = Source.StartActivity("ChargePayment");
        span?.SetTag("order.id", order.Id);

        var ok = await payments.ChargeAsync(order);
        if (!ok)
        {
            Declines.Add(1); // Metric: a number to graph and alert on
            log.LogWarning("Payment declined for order {OrderId}", order.Id);
        }
        return ok;
    }
}
